<?php
declare(strict_types=1);
use Moves\Services\Csrf; use Moves\Services\Helpdesk; use Moves\Services\HelpdeskNotifier; use Moves\Services\SessionAuth; use Moves\Support\CmsView as V;
$user = SessionAuth::current(); $userId = (int) $user['id'];
require dirname(__DIR__) . '/components/support-shell.php';
$status = V::queryString('status'); $result = Helpdesk::customerTickets($userId, ['status' => $status], V::queryPage()); $notes = HelpdeskNotifier::inbox($userId, 'customer', 5); $unread = HelpdeskNotifier::unread($userId, 'customer');
$supportOpen('Meus chamados'); ?>
<?php if ($unread > 0): ?><section class="sp-card"><h2>Novidades (<?= $unread ?>)</h2><?php foreach ($notes as $n): if ($n['read_at'] !== null) { continue; } ?><p><a href="<?= V::e($n['link']) ?>"><?= V::e($n['title']) ?></a> <small><?= V::date($n['created_at']) ?></small></p><?php endforeach; ?><form method="post" action="/suporte/notificacoes/lidas"><input type="hidden" name="csrf_token" value="<?= V::e(Csrf::token()) ?>"><button class="sp-btn">Marcar como lidas</button></form></section><?php endif; ?>
<section class="sp-card"><form class="sp-filter" method="get"><label for="sp-status">Situação</label><select id="sp-status" name="status"><option value="">Todas</option><?php foreach (V::TICKET_STATUS as $key => $label): ?><option value="<?= V::e($key) ?>"<?= $key === $status ? ' selected' : '' ?>><?= V::e($label) ?></option><?php endforeach; ?></select><button class="sp-btn">Filtrar</button></form>
<?php if ($result['rows'] === []): ?><div class="sp-empty"><strong>Nenhum chamado por aqui.</strong><p>Quando precisar de ajuda, abra um chamado e acompanhe tudo nesta página.</p><a class="sp-btn sp-btn-primary" href="/suporte/novo">Abrir chamado</a></div><?php else: ?><ul class="sp-list"><?php foreach ($result['rows'] as $t): ?><li><a href="/suporte/<?= V::e($t['protocol']) ?>"><span><strong><?= V::e($t['subject']) ?></strong><small><?= V::e($t['protocol']) ?> · <?= V::e($t['category_name']) ?><?= $t['organization_name'] ? ' · ' . V::e($t['organization_name']) : '' ?> · <?= V::date($t['last_activity_at']) ?></small></span><em class="sp-status sp-status-<?= V::e($t['status']) ?>"><?= V::e(V::TICKET_STATUS[$t['status']] ?? $t['status']) ?></em></a></li><?php endforeach; ?></ul><?php if ($result['pages'] > 1): ?><nav class="sp-pager" aria-label="Paginação"><?php if ($result['page'] > 1): ?><a class="sp-btn" href="?pagina=<?= $result['page'] - 1 ?>&amp;status=<?= V::e($status) ?>">Anterior</a><?php endif; ?><?php if ($result['page'] < $result['pages']): ?><a class="sp-btn" href="?pagina=<?= $result['page'] + 1 ?>&amp;status=<?= V::e($status) ?>">Próxima</a><?php endif; ?></nav><?php endif; ?><?php endif; ?></section>
<?php $supportClose();
